// Universal FOLIO Logo Loader & Auto-Fallback for Vercel / GitHub
window.FOLIO_LOGO_DATA_URL = "data:image/png;base64,";

function ensureFolioLogos() {
  try {
    var logoUrl = window.FOLIO_LOGO_DATA_URL;
    if (!logoUrl) return;

    var imgs = document.querySelectorAll('img[src*="logo.png"], img[alt*="Logo"], img[alt*="logo"], img[data-folio-logo]');
    imgs.forEach(function(img) {
      img.onerror = function() {
        this.onerror = null;
        this.src = logoUrl;
      };
      if (img.complete && img.naturalWidth === 0) {
        img.src = logoUrl;
      }
    });

    var favs = document.querySelectorAll('link[rel*="icon"]');
    favs.forEach(function(fav) {
      if (fav.href && (fav.href.indexOf("logo.png") !== -1 || fav.href.indexOf("favicon") !== -1)) {
        fav.href = logoUrl;
      }
    });
  } catch (e) {
    console.warn("Logo fallback notice:", e);
  }
}

if (document.readyState === "loading") {
  document.addEventListener("DOMContentLoaded", ensureFolioLogos);
} else {
  ensureFolioLogos();
}
window.addEventListener("load", ensureFolioLogos);

try {
  var observer = new MutationObserver(function(mutations) {
    ensureFolioLogos();
  });
  observer.observe(document.documentElement, { childList: true, subtree: true });
} catch(e) {}
